            seen.add(tag)
            merged.append(tag)
    tags = merged
elif args.remove:
    # 移除模式：按完整文本区分大小写移除指定标签，未指定的标签保持
    # 原顺序；不存在的标签忽略，重复移除结果不变。至少保留一个标签，
    # 否则整次拒绝且不改动任何记录。
    remove_set = set(tags)
    tags = [tag for tag in existing_tags if tag not in remove_set]
    if not tags:
        raise CliError("不能移除全部标签：素材至少保留一个标签")

